          "evaluating": false,
          "history": [
            {
              "percent_value": 68,
              "size_value": null,
              "boolean_value": null,
              "rationale": "Focused non-git-mutating API/CLI feature with clean error handling and well-isolated httptest + flag tests, but the core decision helper applyTrailBranchChange and the full runTrailUpdate rename/attach paths lack dedicated coverage; gates would plausibly pass (couldn't run go/mise here to confirm).",
              "run_id": "019f4717-0c8f-772d-a7ea-eac41d0c5ff1",
              "head_sha": "14c8e507e0bcc674465e9151479a103d242ca705",
