            {
              "percent_value": 68,
              "size_value": null,
              "boolean_value": null,
              "rationale": "Clean, low-risk control-plane HTTP command (not git-mutating) with well-isolated unit tests covering the API helper, its 409 path, and flag wiring, plus reuse of already-tested selector logic; main gap is that the branch-heavy new orchestration function applyTrailBranchChange and the PATCH-skip logic have no direct tests, and gates could not be executed here.",
              "run_id": "019f470b-1298-78ff-9fb3-0d0f3e56f593",
              "head_sha": "0385bb234f79f8c2327ddf4835e3cd087ec9873e",
              "updated_at": "2026-07-09T13:24:00.000Z"
            }
          ],
          "run_id": "019f4717-0c8f-772d-a7ea-eac41d0c5ff1",
          "head_sha": "14c8e507e0bcc674465e9151479a103d242ca705",
          "updated_at": "2026-07-09T13:36:39.306Z"
        },
        {
          "key": "security",
          "label": "Security",
          "value_type": "percent",
          "percent_value": 8,
          "size_value": null,
          "boolean_value": null,
          "rationale": "Small, well-tested feature scoped to `entire trail update`; user-supplied branch names are validated via ValidateBranchName/git check-ref-format before use, paths interpolate only integer trail numbers, and there are no dependency, CI, auth, hook, or redaction changes.",
          "polarity": "lower_is_better",
